-- ---------------------------------------------------------------- 20261106050000_staff_permissions_appeals.sql
-- =============================================================================
-- Staff permissions, appeals, audit search, theme / bot moderation (20261106050000)
--
--   * Granular staff permissions. profiles.staff_permissions (NULL = the role's
--     defaults, which are exactly what each rank could do before, so nothing
--     changes until an owner narrows someone down). Owners / founders always
--     have every permission. Checked by staff_can() inside every moderation
--     function — the app hiding a button is never the protection.
--       accounts  limit / very-limit / restore accounts      (moderator+)
--       ban       ban and unban accounts                     (moderator+)
--       badges    award badges                               (moderator+)
--       servers   review / verify / close / ban servers      (moderator+)
--       marketplace  remove / restore themes & styles        (moderator+)
--       apps      disable / enable bots and apps             (moderator+)
--       audit     read the staff audit log                   (moderator+)
--       reports   the Report Centre                          (admin+)
--       appeals   decide appeals                             (admin+)
--   * Appeals: people can appeal an account restriction, a removed marketplace
--     item or a disabled bot, once at a time; staff accept (undoes it) or deny
--     with a reply; the person is notified either way.
--   * Reports for marketplace items and bots (report_item), shown in the
--     Report Centre next to message / user reports.
--   * mod_log_search: audit log search and filters.
--
-- Safe to run more than once.
-- =============================================================================

-- ------------------------------------------------------- staff permissions --
create or replace function public.staff_permission_keys()
returns text[] language sql immutable set search_path = '' as $$
  select array['accounts', 'ban', 'badges', 'servers', 'marketplace', 'apps', 'audit', 'reports', 'appeals']::text[];
$$;

alter table public.profiles add column if not exists staff_permissions text[];
do $$ begin
  alter table public.profiles add constraint profiles_staff_permissions_valid
    check (staff_permissions is null or staff_permissions <@ array['accounts', 'ban', 'badges', 'servers', 'marketplace', 'apps', 'audit', 'reports', 'appeals']::text[]);
exception when duplicate_object then null; end $$;

create or replace function public.staff_permissions_for(p_user uuid default auth.uid())
returns text[] language sql stable security definer set search_path = '' as $$
  select case
    when public.is_top_staff(p_user) then public.staff_permission_keys()
    when public.platform_rank(p_user) < 1 then '{}'::text[]
    else coalesce((select staff_permissions from public.profiles where id = p_user),
                  case when public.platform_rank(p_user) >= 2 then public.staff_permission_keys()
                       else array['accounts', 'ban', 'badges', 'servers', 'marketplace', 'apps', 'audit']::text[] end)
  end;
$$;

create or replace function public.staff_can(p_perm text, p_user uuid default auth.uid())
returns boolean language sql stable security definer set search_path = '' as $$
  select p_perm = any (public.staff_permissions_for(p_user));
$$;

create or replace function public.my_staff_permissions()
returns text[] language sql stable security definer set search_path = '' as $$
  select public.staff_permissions_for(auth.uid());
$$;

-- Owners / founders set what a staff member may do. NULL = back to the role's defaults.
create or replace function public.mod_set_staff_permissions(p_user uuid, p_perms text[])
returns text[] language plpgsql security definer set search_path = '' as $$
declare
  v_clean text[];
begin
  if not public.is_top_staff() then raise exception 'only Venband owners can change staff permissions'; end if;
  if p_user = auth.uid() then raise exception 'you can''t change your own permissions'; end if;
  if public.platform_rank(p_user) < 1 then raise exception 'they aren''t Venband staff'; end if;
  if public.is_top_staff(p_user) then raise exception 'owners always have every permission'; end if;
  if p_perms is not null then
    if not (p_perms <@ public.staff_permission_keys()) then raise exception 'unknown permission'; end if;
    select coalesce(array_agg(distinct x order by x), '{}') into v_clean from unnest(p_perms) x;
  end if;
  update public.profiles set staff_permissions = v_clean where id = p_user;
  insert into public.mod_actions (actor_id, target_user, action, detail)
  values (auth.uid(), p_user, 'staff_permissions', coalesce(array_to_string(v_clean, ', '), 'role defaults'));
  return public.staff_permissions_for(p_user);
end;
$$;

-- ----------------------------------------- existing tools, now permission-checked --
create or replace function public.mod_set_account_status(p_user uuid, p_status text, p_reason text default '', p_server uuid default null)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if p_status not in ('active', 'limited', 'very_limited', 'banned') then raise exception 'unknown status'; end if;
  if p_user = auth.uid() or not public.mod_can_target(p_user) then raise exception 'you can''t change this account'; end if;
  -- banning / unbanning needs the "ban" permission, other restrictions "accounts"
  if not public.staff_can(case when p_status = 'banned' or (select account_status from public.profiles where id = p_user) = 'banned'
                               then 'ban' else 'accounts' end) then
    raise exception 'your staff permissions don''t include this';
  end if;
  update public.profiles set account_status = p_status where id = p_user;
  -- banned accounts are signed out everywhere and can't sign in again
  update auth.users set banned_until = case when p_status = 'banned' then 'infinity'::timestamptz end
  where id = p_user;
  if p_status = 'banned' then delete from auth.sessions where user_id = p_user; end if;
  insert into public.mod_actions (actor_id, target_user, action, detail, reason)
  values (auth.uid(), p_user, 'account_status', p_status, left(coalesce(p_reason, ''), 1000));
  if p_status in ('limited', 'very_limited', 'banned') then
    perform public.venband_notice(p_user, p_status, p_reason, p_server);
  end if;
end;
$$;

create or replace function public.mod_set_badges(p_user uuid, p_badges text[])
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_new text[];
  v_old text[];
  v_staff_badges text[] := array['owner', 'admin', 'moderator', 'staff', 'developer', 'verified', 'verified_bot', 'verified_server'];
begin
  if not public.mod_can_target(p_user) then raise exception 'you can''t change this account'; end if;
  if not public.staff_can('badges') then raise exception 'your staff permissions don''t include badges'; end if;
  select coalesce(array_agg(distinct b order by b), '{}') into v_new
  from unnest(coalesce(p_badges, '{}')) b where b = any (public.all_badges());
  select badges into v_old from public.profiles where id = p_user;
  if not public.is_top_staff() then
    if public.platform_rank() < 2 and (
         (select coalesce(array_agg(b), '{}') from unnest(v_new) b where b = any (v_staff_badges))
         is distinct from
         (select coalesce(array_agg(b order by b), '{}') from unnest(v_old) b where b = any (v_staff_badges))) then
      raise exception 'only admins can change staff and verification badges';
    end if;
    if public.platform_rank() < 3 and (('owner' = any (v_new)) <> ('owner' = any (v_old))) then
      raise exception 'only the owner can change the owner badge';
    end if;
  end if;
  update public.profiles set badges = v_new where id = p_user;
  insert into public.mod_actions (actor_id, target_user, action, detail)
  values (auth.uid(), p_user, 'badges', array_to_string(v_new, ', '));
end;
$$;

create or replace function public.mod_server_action(p_server uuid, p_action text, p_reason text default '')
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_owner uuid;
begin
  if not public.is_staff() then raise exception 'staff only'; end if;
  if not public.staff_can('servers') then raise exception 'your staff permissions don''t include servers'; end if;
  select owner_id into v_owner from public.servers where id = p_server;
  if v_owner is null then raise exception 'server not found'; end if;
  perform set_config('venband.mod', 'on', true);
  case p_action
    when 'review'   then update public.servers set status = 'review' where id = p_server;
    when 'approve'  then update public.servers set status = 'active' where id = p_server;
    when 'reject'   then
      update public.servers set status = 'closed', verified = false where id = p_server;
      if public.platform_rank(v_owner) < public.platform_rank() then
        update public.profiles set account_status = 'very_limited'
        where id = v_owner and account_status in ('active', 'limited');
        if found then
          perform public.venband_notice(v_owner, 'very_limited', p_reason, p_server);
        end if;
      end if;
    when 'ban'      then update public.servers set status = 'banned', verified = false where id = p_server;
    when 'unban'    then update public.servers set status = 'active' where id = p_server;
    when 'verify'   then update public.servers set verified = true where id = p_server;
    when 'unverify' then update public.servers set verified = false where id = p_server;
    else raise exception 'unknown action';
  end case;
  perform set_config('venband.mod', 'off', true);
  insert into public.mod_actions (actor_id, target_server, target_user, action, reason)
  values (auth.uid(), p_server, v_owner, 'server_' || p_action, left(coalesce(p_reason, ''), 1000));
end;
$$;

create or replace function public.handle_report(p_report uuid, p_status text, p_note text default '')
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not public.staff_can('reports') then raise exception 'your staff permissions don''t include reports'; end if;
  if p_status not in ('under_review', 'actioned', 'dismissed') then raise exception 'unknown status'; end if;
  update public.reports
  set status = p_status, handled_by = auth.uid(), handled_note = left(coalesce(p_note, ''), 1000),
      handled_at = case when p_status = 'under_review' then null else now() end
  where id = p_report;
  insert into public.mod_actions (actor_id, target_user, action, detail, reason)
  select auth.uid(), r.target_user, 'report_' || p_status, r.kind, left(coalesce(p_note, ''), 1000)
  from public.reports r where r.id = p_report;
end;
$$;

create or replace function public.mod_log(p_limit integer default 50)
returns table (id uuid, actor text, target_user text, target_server text, action text, detail text,
               reason text, created_at timestamptz)
language sql stable security definer set search_path = '' as $$
  select m.id, a.username, u.username, s.name, m.action, m.detail, m.reason, m.created_at
  from public.mod_actions m
  left join public.profiles a on a.id = m.actor_id
  left join public.profiles u on u.id = m.target_user
  left join public.servers s on s.id = m.target_server
  where public.is_staff() and public.staff_can('audit')
  order by m.created_at desc
  limit least(coalesce(p_limit, 50), 200);
$$;

create or replace function public.theme_set_status(p_theme uuid, p_status text, p_reason text default '')
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  t public.themes%rowtype;
  v_staff boolean := public.is_staff() and public.staff_can('marketplace');
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if p_status not in ('published', 'unpublished', 'removed') then raise exception 'unknown status'; end if;
  select * into t from public.themes where id = p_theme for update;
  if not found then raise exception 'not found'; end if;

  if p_status = 'removed' or t.status = 'removed' then
    if not v_staff then raise exception 'only Venband staff can remove or restore marketplace items'; end if;
    if p_status = 'removed' and char_length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'give a reason for removing it'; end if;
    if p_status <> 'removed' and t.version < 1 then raise exception 'it was never published'; end if;
    update public.themes
       set status = p_status, updated_at = now(),
           removed_reason = case when p_status = 'removed' then left(btrim(p_reason), 500) else null end
     where id = p_theme;
    insert into public.mod_actions (actor_id, target_user, action, detail, reason)
    values (v_uid, t.author_id, 'marketplace_' || case when p_status = 'removed' then 'remove' else 'restore' end,
            t.kind || ' “' || t.name || '” (' || t.id || ')', left(coalesce(p_reason, ''), 1000));
    return;
  end if;

  if t.author_id <> v_uid then raise exception 'only the creator can change this'; end if;
  if p_status = 'published' and t.version < 1 then raise exception 'publish it first'; end if;
  update public.themes set status = p_status, updated_at = now() where id = p_theme;
end;
$$;

-- ------------------------------------------------------------ audit search --
create or replace function public.mod_log_search(
  p_query text default '', p_action text default '', p_from timestamptz default null, p_to timestamptz default null,
  p_before timestamptz default null, p_limit integer default 100)
returns table (id uuid, actor text, actor_id uuid, target_user text, target_user_id uuid, target_server text,
               target_server_id uuid, action text, detail text, reason text, created_at timestamptz)
language sql stable security definer set search_path = '' as $$
  select m.id, a.username, m.actor_id, u.username, m.target_user, s.name, m.target_server, m.action, m.detail, m.reason, m.created_at
  from public.mod_actions m
  left join public.profiles a on a.id = m.actor_id
  left join public.profiles u on u.id = m.target_user
  left join public.servers s on s.id = m.target_server
  where public.is_staff() and public.staff_can('audit')
    and (coalesce(p_action, '') = '' or m.action like replace(replace(p_action, '%', ''), '_', '\_') || '%')
    and (p_from is null or m.created_at >= p_from)
    and (p_to is null or m.created_at < p_to)
    and (p_before is null or m.created_at < p_before)
    and (coalesce(btrim(p_query), '') = ''
         or a.username ilike '%' || btrim(p_query) || '%' or u.username ilike '%' || btrim(p_query) || '%'
         or s.name ilike '%' || btrim(p_query) || '%' or m.detail ilike '%' || btrim(p_query) || '%'
         or m.reason ilike '%' || btrim(p_query) || '%' or m.target_user::text = btrim(p_query)
         or m.target_server::text = btrim(p_query) or m.actor_id::text = btrim(p_query))
  order by m.created_at desc
  limit least(greatest(coalesce(p_limit, 100), 1), 200);
$$;

-- ------------------------------------------------- bots: disable / enable --
create or replace function public.mod_app_action(p_app uuid, p_action text, p_reason text default '')
returns void language plpgsql security definer set search_path = '' as $$
declare
  a public.applications%rowtype;
begin
  if not public.staff_can('apps') then raise exception 'your staff permissions don''t include bots and apps'; end if;
  if p_action not in ('disable', 'enable') then raise exception 'unknown action'; end if;
  select * into a from public.applications where id = p_app;
  if not found then raise exception 'not found'; end if;
  if a.owner_id = '3fff0000-0000-4000-8000-0000000000bd' and not public.is_top_staff() then
    raise exception 'only owners can change Venband''s own apps';
  end if;
  if p_action = 'disable' and char_length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'give a reason'; end if;
  perform set_config('venband.mod', 'on', true);
  update public.applications set status = case when p_action = 'disable' then 'disabled' else 'active' end where id = p_app;
  perform set_config('venband.mod', 'off', true);
  insert into public.mod_actions (actor_id, target_user, action, detail, reason)
  values (auth.uid(), a.owner_id, 'app_' || p_action, a.name || ' (' || a.id || ')', left(coalesce(p_reason, ''), 1000));
  perform public.notify(a.owner_id, 'platform', 'app_' || p_action,
    case when p_action = 'disable' then 'Your bot “' || a.name || '” was disabled' else 'Your bot “' || a.name || '” is active again' end,
    case when p_action = 'disable' then 'Venband staff disabled it: ' || left(btrim(p_reason), 400) || E'\nYou can appeal in Settings → Security → Appeals.'
         else 'Venband staff lifted the restriction. It can post again.' end,
    case when p_action = 'disable' then 'warning' else 'info' end,
    case when p_action = 'disable' then array['open_appeals'] else '{}'::text[] end,
    jsonb_build_object('app', a.id));
end;
$$;

-- --------------------------------------------- reports for themes and bots --
alter table public.reports add column if not exists target_ref uuid;
alter table public.reports drop constraint if exists reports_kind_check;
alter table public.reports add constraint reports_kind_check check (kind in ('message', 'user', 'theme', 'app'));

-- message / user reports are inserted directly (they carry evidence decrypted on
-- the reporter's device); theme / bot reports only through report_item()
drop policy if exists reports_insert on public.reports;
create policy reports_insert on public.reports for insert to authenticated
  with check (
    reporter_id = auth.uid() and status = 'under_review' and handled_by is null
    and kind in ('message', 'user')
    and target_user is distinct from auth.uid()
    and (select count(*) from public.reports r where r.reporter_id = auth.uid() and r.created_at > now() - interval '1 hour') < 20
  );
drop policy if exists reports_select on public.reports;
create policy reports_select on public.reports for select to authenticated
  using (reporter_id = auth.uid() or public.staff_can('reports'));

create or replace function public.report_item(p_kind text, p_ref uuid, p_reason text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_name text;
  v_id uuid;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if char_length(btrim(coalesce(p_reason, ''))) not between 3 and 1000 then raise exception 'say what''s wrong (3–1000 characters)'; end if;
  if p_kind = 'theme' then
    select author_id, name into v_owner, v_name from public.themes where id = p_ref and status = 'published';
  elsif p_kind = 'app' then
    select owner_id, name into v_owner, v_name from public.applications where id = p_ref;
  else
    raise exception 'unknown kind';
  end if;
  if v_owner is null then raise exception 'not found'; end if;
  if v_owner = v_uid then raise exception 'you can''t report your own'; end if;
  if (select count(*) from public.reports r where r.reporter_id = v_uid and r.created_at > now() - interval '1 hour') >= 20 then
    raise exception 'too many reports — try again later';
  end if;
  if exists (select 1 from public.reports where reporter_id = v_uid and kind = p_kind and target_ref = p_ref and status = 'under_review') then
    raise exception 'you already reported this — staff will look at it';
  end if;
  insert into public.reports (reporter_id, kind, target_user, target_ref, reason, evidence)
  values (v_uid, p_kind, v_owner, p_ref, btrim(p_reason),
          jsonb_build_array(jsonb_build_object('id', p_ref, 'author_id', v_owner, 'author', coalesce(v_name, ''), 'text', coalesce(v_name, ''), 'at', now())))
  returning id into v_id;
  return v_id;
end;
$$;

-- ----------------------------------------------------------------- appeals --
create table if not exists public.appeals (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles (id) on delete cascade,
  kind        text not null check (kind in ('account', 'theme', 'app')),
  target_ref  uuid,
  subject     text not null default '' check (char_length(subject) <= 200),
  message     text not null check (char_length(btrim(message)) between 10 and 2000),
  status      text not null default 'open' check (status in ('open', 'accepted', 'denied')),
  handled_by  uuid references public.profiles (id) on delete set null,
  response    text not null default '' check (char_length(response) <= 1000),
  created_at  timestamptz not null default now(),
  handled_at  timestamptz
);
create unique index if not exists appeals_one_open on public.appeals (user_id, kind, coalesce(target_ref, '00000000-0000-0000-0000-000000000000'::uuid)) where status = 'open';
create index if not exists appeals_status_idx on public.appeals (status, created_at);
alter table public.appeals enable row level security;
drop policy if exists appeals_select on public.appeals;
create policy appeals_select on public.appeals for select to authenticated
  using (user_id = auth.uid() or public.staff_can('appeals'));
revoke insert, update, delete on public.appeals from authenticated, anon;
grant select on public.appeals to authenticated;

create or replace function public.submit_appeal(p_kind text, p_ref uuid, p_message text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_subject text;
  v_id uuid;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if char_length(btrim(coalesce(p_message, ''))) not between 10 and 2000 then raise exception 'explain in 10–2000 characters'; end if;
  if p_kind = 'account' then
    select account_status into v_subject from public.profiles where id = v_uid;
    if v_subject is null or v_subject = 'active' then raise exception 'your account isn''t restricted'; end if;
    p_ref := null;
  elsif p_kind = 'theme' then
    select name into v_subject from public.themes where id = p_ref and author_id = v_uid and status = 'removed';
    if v_subject is null then raise exception 'that item wasn''t removed by staff'; end if;
  elsif p_kind = 'app' then
    select name into v_subject from public.applications where id = p_ref and owner_id = v_uid and status = 'disabled';
    if v_subject is null then raise exception 'that bot isn''t disabled'; end if;
  else
    raise exception 'unknown kind';
  end if;
  if exists (select 1 from public.appeals where user_id = v_uid and kind = p_kind and target_ref is not distinct from p_ref and status = 'open') then
    raise exception 'you already have an open appeal for this';
  end if;
  if exists (select 1 from public.appeals where user_id = v_uid and kind = p_kind and target_ref is not distinct from p_ref
             and status = 'denied' and handled_at > now() - interval '7 days') then
    raise exception 'this appeal was denied recently — you can appeal again 7 days after the decision';
  end if;
  if (select count(*) from public.appeals where user_id = v_uid and created_at > now() - interval '1 day') >= 5 then
    raise exception 'too many appeals today';
  end if;
  insert into public.appeals (user_id, kind, target_ref, subject, message)
  values (v_uid, p_kind, p_ref, left(v_subject, 200), btrim(p_message))
  returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.handle_appeal(p_appeal uuid, p_accept boolean, p_response text default '')
returns void language plpgsql security definer set search_path = '' as $$
declare
  a public.appeals%rowtype;
begin
  if not public.staff_can('appeals') then raise exception 'your staff permissions don''t include appeals'; end if;
  select * into a from public.appeals where id = p_appeal for update;
  if not found then raise exception 'not found'; end if;
  if a.status <> 'open' then raise exception 'already decided'; end if;
  if a.user_id = auth.uid() then raise exception 'you can''t decide your own appeal'; end if;
  if not p_accept and char_length(btrim(coalesce(p_response, ''))) < 3 then raise exception 'tell them why it was denied'; end if;

  if p_accept then
    if a.kind = 'account' then
      if not public.mod_can_target(a.user_id) then raise exception 'you can''t change this account'; end if;
      update public.profiles set account_status = 'active' where id = a.user_id;
      update auth.users set banned_until = null where id = a.user_id;
    elsif a.kind = 'theme' then
      update public.themes set status = 'published', removed_reason = null, updated_at = now()
       where id = a.target_ref and status = 'removed' and version >= 1;
    elsif a.kind = 'app' then
      perform set_config('venband.mod', 'on', true);
      update public.applications set status = 'active' where id = a.target_ref;
      perform set_config('venband.mod', 'off', true);
    end if;
  end if;

  update public.appeals set status = case when p_accept then 'accepted' else 'denied' end,
         handled_by = auth.uid(), response = left(btrim(coalesce(p_response, '')), 1000), handled_at = now()
   where id = p_appeal;
  insert into public.mod_actions (actor_id, target_user, action, detail, reason)
  values (auth.uid(), a.user_id, 'appeal_' || case when p_accept then 'accepted' else 'denied' end,
          a.kind || ': ' || a.subject, left(coalesce(p_response, ''), 1000));
  perform public.notify(a.user_id, 'platform', 'appeal_result',
    case when p_accept then 'Your appeal was accepted' else 'Your appeal was denied' end,
    case when p_accept then 'Venband staff reviewed your appeal about ' || a.subject || ' and lifted it.'
         else 'Venband staff reviewed your appeal about ' || a.subject || '. Their reply: ' || left(btrim(p_response), 600) end,
    case when p_accept then 'info' else 'warning' end, array['open_appeals'], jsonb_build_object('appeal', a.id));
end;
$$;

-- ------------------------------------------------------------------ grants --
revoke execute on function public.staff_permissions_for(uuid) from public, anon, authenticated;
revoke execute on function public.staff_can(text, uuid) from public, anon;
grant execute on function public.staff_can(text, uuid) to authenticated;
revoke execute on function public.my_staff_permissions() from public, anon;
grant execute on function public.my_staff_permissions() to authenticated;
revoke execute on function public.mod_set_staff_permissions(uuid, text[]) from public, anon;
grant execute on function public.mod_set_staff_permissions(uuid, text[]) to authenticated;
revoke execute on function public.mod_log_search(text, text, timestamptz, timestamptz, timestamptz, integer) from public, anon;
grant execute on function public.mod_log_search(text, text, timestamptz, timestamptz, timestamptz, integer) to authenticated;
revoke execute on function public.mod_app_action(uuid, text, text) from public, anon;
grant execute on function public.mod_app_action(uuid, text, text) to authenticated;
revoke execute on function public.report_item(text, uuid, text) from public, anon;
grant execute on function public.report_item(text, uuid, text) to authenticated;
revoke execute on function public.submit_appeal(text, uuid, text) from public, anon;
grant execute on function public.submit_appeal(text, uuid, text) to authenticated;
revoke execute on function public.handle_appeal(uuid, boolean, text) from public, anon;
grant execute on function public.handle_appeal(uuid, boolean, text) to authenticated;

notify pgrst, 'reload schema';

-- ---------------------------------------------------------------- 20261106060000_memories_archive.sql
-- =============================================================================
-- Memories: 30 kept / 10 showing, archive, expiry, audience, reporting (20261106060000)
--
--   * keep up to 30 memories; up to 10 show on your profile at once, the rest
--     are archived (only you see them) and can be shown again
--   * optional expiry: after it, a memory stops showing to others (you keep it)
--   * audience per memory: everyone who can see your profile, friends only, or
--     only you
--   * memory media is only served for memories the viewer is allowed to see —
--     before, anyone who could see your profile could list every file in your
--     memories folder (archived / friends-only ones included)
--   * memories can be reported (report_item 'memory'); staff can remove them
--
-- Safe to run more than once.
-- =============================================================================

alter table public.memories add column if not exists active boolean not null default true;
alter table public.memories add column if not exists expires_at timestamptz;
alter table public.memories add column if not exists audience text not null default 'everyone';
do $$ begin
  alter table public.memories add constraint memories_audience_check check (audience in ('everyone', 'friends', 'only_me'));
exception when duplicate_object then null; end $$;

-- showing = active and not expired
create or replace function public.memory_showing(p_active boolean, p_expires timestamptz)
returns boolean language sql stable set search_path = '' as $$
  select p_active and (p_expires is null or p_expires > now());
$$;

create or replace function public.memory_visible(p_memory uuid, p_user uuid default auth.uid())
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.memories m
     where m.id = p_memory
       and (m.user_id = p_user
            or (public.memory_showing(m.active, m.expires_at)
                and m.audience <> 'only_me'
                and public.can_see_memories(m.user_id, p_user)
                and (m.audience = 'everyone' or public.are_friends(m.user_id, p_user)))
            or public.staff_can('reports', p_user)));
$$;

create or replace function public.guard_memory()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if split_part(new.path, '/', 1) <> new.user_id::text then
    raise exception 'memory media must be stored in your own folder';
  end if;
  if new.expires_at is not null and (new.expires_at < now() - interval '1 minute' or new.expires_at > now() + interval '366 days') then
    raise exception 'pick an expiry within the next year';
  end if;
  perform pg_advisory_xact_lock(hashtext('memories:' || new.user_id::text));
  if tg_op = 'INSERT' and (select count(*) from public.memories where user_id = new.user_id) >= 30 then
    raise exception 'You can keep up to 30 memories. Delete one to add another.';
  end if;
  if public.memory_showing(new.active, new.expires_at)
     and (tg_op = 'INSERT' or not public.memory_showing(old.active, old.expires_at))
     and (select count(*) from public.memories
           where user_id = new.user_id and id <> new.id and public.memory_showing(active, expires_at)) >= 10 then
    raise exception 'Up to 10 memories can show at once. Archive one first.';
  end if;
  return new;
end;
$$;
drop trigger if exists memories_guard on public.memories;
create trigger memories_guard before insert or update of active, expires_at on public.memories
  for each row execute function public.guard_memory();

drop policy if exists memories_select on public.memories;
create policy memories_select on public.memories for select to authenticated
  using (public.memory_visible(id));
grant update (caption, active, expires_at, audience) on public.memories to authenticated;

-- staff remove reported memories (the file too)
drop policy if exists memories_delete on public.memories;
create policy memories_delete on public.memories for delete to authenticated
  using (user_id = auth.uid() or public.staff_can('reports'));

-- media: only files of memories you may see (the owner always sees their folder)
drop policy if exists venband_memories_read on storage.objects;
create policy venband_memories_read on storage.objects for select to authenticated
  using (bucket_id = 'memories'
         and (split_part(name, '/', 1) = auth.uid()::text
              or exists (select 1 from public.memories m where m.path = name and public.memory_visible(m.id))));
drop policy if exists venband_memories_delete on storage.objects;
create policy venband_memories_delete on storage.objects for delete to authenticated
  using (bucket_id = 'memories' and (split_part(name, '/', 1) = auth.uid()::text or public.staff_can('reports')));

-- ------------------------------------------------------------- reporting --
alter table public.reports drop constraint if exists reports_kind_check;
alter table public.reports add constraint reports_kind_check check (kind in ('message', 'user', 'theme', 'app', 'memory'));

create or replace function public.report_item(p_kind text, p_ref uuid, p_reason text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_name text;
  v_id uuid;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if char_length(btrim(coalesce(p_reason, ''))) not between 3 and 1000 then raise exception 'say what''s wrong (3–1000 characters)'; end if;
  if p_kind = 'theme' then
    select author_id, name into v_owner, v_name from public.themes where id = p_ref and status = 'published';
  elsif p_kind = 'app' then
    select owner_id, name into v_owner, v_name from public.applications where id = p_ref;
  elsif p_kind = 'memory' then
    -- only a memory you can actually see
    select m.user_id, coalesce(nullif(m.caption, ''), 'Memory') into v_owner, v_name
      from public.memories m where m.id = p_ref and public.memory_visible(m.id, v_uid);
  else
    raise exception 'unknown kind';
  end if;
  if v_owner is null then raise exception 'not found'; end if;
  if v_owner = v_uid then raise exception 'you can''t report your own'; end if;
  if (select count(*) from public.reports r where r.reporter_id = v_uid and r.created_at > now() - interval '1 hour') >= 20 then
    raise exception 'too many reports — try again later';
  end if;
  if exists (select 1 from public.reports where reporter_id = v_uid and kind = p_kind and target_ref = p_ref and status = 'under_review') then
    raise exception 'you already reported this — staff will look at it';
  end if;
  insert into public.reports (reporter_id, kind, target_user, target_ref, reason, evidence)
  values (v_uid, p_kind, v_owner, p_ref, btrim(p_reason),
          jsonb_build_array(jsonb_build_object('id', p_ref, 'author_id', v_owner, 'author', coalesce(v_name, ''), 'text', coalesce(v_name, ''), 'at', now())))
  returning id into v_id;
  return v_id;
end;
$$;

revoke execute on function public.memory_visible(uuid, uuid) from public, anon;
grant execute on function public.memory_visible(uuid, uuid) to authenticated;
revoke execute on function public.guard_memory() from public, anon, authenticated;

notify pgrst, 'reload schema';

-- ---------------------------------------------------------------- 20261106070000_category_order.sql
-- =============================================================================
-- Category order (20261106070000)
--
-- Categories can be dragged anywhere — empty ones too. Their order is the
-- order of servers.categories (every category, empty or not). Before, the order
-- came only from channel positions, so an empty category always sat at the
-- bottom, and only Manage Server could touch servers.categories.
-- reorder_categories() needs Manage Channels (like reordering channels).
--
-- Safe to run more than once.
-- =============================================================================

create or replace function public.reorder_categories(p_server uuid, p_names text[])
returns text[] language plpgsql security definer set search_path = '' as $$
declare
  v_out text[] := '{}';
  n text;
begin
  if not public.has_permission(p_server, 8) then raise exception 'you need Manage Channels'; end if;
  if cardinality(coalesce(p_names, '{}')) > 200 then raise exception 'too many categories'; end if;
  foreach n in array coalesce(p_names, '{}') loop
    n := left(btrim(n), 100);
    if n <> '' and not (n = any (v_out)) then v_out := v_out || n; end if;
  end loop;
  -- categories that exist only through their channels are kept (at the end)
  v_out := v_out || array(
    select distinct c.category from public.channels c
     where c.server_id = p_server and c.category <> '' and not (c.category = any (v_out)));
  update public.servers set categories = v_out where id = p_server;
  return v_out;
end;
$$;

revoke execute on function public.reorder_categories(uuid, text[]) from public, anon;
grant execute on function public.reorder_categories(uuid, text[]) to authenticated;

notify pgrst, 'reload schema';

-- ---------------------------------------------------------------- 20261106080000_column_grants.sql
-- =============================================================================
-- Make the column-level grants authoritative (20261106080000)
--
-- Venband limits which columns signed-in users can read or write with column
-- grants (bot token hashes are never readable; on profiles you can only edit
-- your own display fields, …). But some Supabase projects grant ALL on every
-- table to `authenticated` by default, and a table-wide grant overrides the
-- column limits — e.g. anyone who could see a bot could read its token_hash.
-- For each table + privilege the migrations only grant on some columns, revoke
-- the table-wide privilege and grant exactly those columns (generated by
-- scripts/column-grants.mjs). Also grants applications.banner_url, which the
-- app reads and sets but no migration granted.
--
-- On projects without the broad default this changes nothing. Safe to run more
-- than once.
-- =============================================================================

revoke select on public.applications from authenticated;
grant select (id, owner_id, name, description, preset, icon_url, banner_url, color, token_hint, status, created_at, updated_at, tags, script) on public.applications to authenticated;
revoke update on public.applications from authenticated;
grant update (name, description, icon_url, banner_url, color, tags, script) on public.applications to authenticated;
revoke select on public.bot_commands from authenticated;
grant select (app_id, name, description, response) on public.bot_commands to authenticated;
revoke update on public.channels from authenticated;
grant update (name, topic, category, position, is_private, settings, color) on public.channels to authenticated;
revoke update on public.invites from authenticated;
grant update (paused, label) on public.invites to authenticated;
revoke update on public.memories from authenticated;
grant update (caption, active, expires_at, audience) on public.memories to authenticated;
revoke update on public.messages from authenticated;
grant update (epoch, iv, ciphertext, signature, author_key_id) on public.messages to authenticated;
revoke update on public.notifications from authenticated;
grant update (read_at) on public.notifications to authenticated;
revoke update on public.polls from authenticated;
grant update (expires_at) on public.polls to authenticated;
revoke update on public.profiles from authenticated;
grant update (display_name, avatar_color, about, pronouns, status_text, status_emoji, presence, banner_color, banner_color2, accent_color, nameplate, language, onboarded, avatar_url, banner_url, avatar_frame, name_style, nameplate_style, profile_effect) on public.profiles to authenticated;
revoke select on public.server_bots from authenticated;
grant select (id, server_id, app_id, added_by, settings, webhook_channel, created_at) on public.server_bots to authenticated;
revoke update on public.server_members from authenticated;
grant update (nickname) on public.server_members to authenticated;
revoke update on public.threads from authenticated;
grant update (name, locked, archived, tags, pinned, solved) on public.threads to authenticated;

notify pgrst, 'reload schema';

-- ---------------------------------------------------------------- 20261106090000_gif_library.sql
-- =============================================================================
-- Your GIF library (20261106090000)
--
-- GIFs you save ("Save as GIF" on a picture, the star on a GIF someone sent you,
-- /gif on a reply) are stored here so they show in your GIF favourites on every
-- device. Messages stay end-to-end encrypted: only what YOU choose to save
-- lands here, under an unguessable name in your own folder.
--
-- Safe to run more than once.
-- =============================================================================

insert into storage.buckets (id, name, public, file_size_limit)
values ('gifs', 'gifs', true, 15728640)
on conflict (id) do update set public = true, file_size_limit = 15728640;
do $$ begin
  update storage.buckets set allowed_mime_types = array['image/gif'] where id = 'gifs';
exception when undefined_column then null; end $$;

-- How many GIFs someone has saved. A definer function, because a policy on
-- storage.objects that reads storage.objects itself recurses forever — and as
-- all insert policies are checked together, that broke EVERY upload.
create or replace function public.my_gif_count()
returns integer language sql stable security definer set search_path = '' as $$
  select count(*)::int from storage.objects o
   where o.bucket_id = 'gifs' and split_part(o.name, '/', 1) = auth.uid()::text;
$$;
revoke execute on function public.my_gif_count() from public, anon;
grant execute on function public.my_gif_count() to authenticated;

drop policy if exists venband_gifs_write on storage.objects;
create policy venband_gifs_write on storage.objects for insert to authenticated
  with check (bucket_id = 'gifs' and split_part(name, '/', 1) = auth.uid()::text
              and public.my_gif_count() < 500); -- at most 500 saved GIFs each
drop policy if exists venband_gifs_delete on storage.objects;
create policy venband_gifs_delete on storage.objects for delete to authenticated
  using (bucket_id = 'gifs' and split_part(name, '/', 1) = auth.uid()::text);

notify pgrst, 'reload schema';

-- ---------------------------------------------------------------- 20261106100000_builtin_bots.sql
-- =============================================================================
-- Built-in bots + the official bot's look (20261106100000)
--
--   * the official Venband bot gets the Venband logo (512×512) as its picture
--     and its own banner
--   * Venband's own bots appear in App Discovery for every server, each with its
--     own picture (public/bots/*.svg): Greeter (welcome + auto roles),
--     Gatekeeper (verification), Word Guess (a word game), Announcer (website /
--     webhook posts) and Mod Toolkit (moderation). They're owned by the Venband
--     system account, so they show as official.
--
-- Safe to run more than once.
-- =============================================================================

update public.applications
   set icon_url = '/icon-512.png',
       banner_url = '/bots/venband-banner.svg',
       description = 'The official Venband bot. It sends account notices, security alerts and staff messages — and never asks for your password.'
 where owner_id = '3fff0000-0000-4000-8000-0000000000bd' and name = 'Venband';

insert into public.applications (owner_id, name, preset, description, color, icon_url, tags)
select '3fff0000-0000-4000-8000-0000000000bd', v.name, v.preset, v.description, v.color, v.icon, v.tags
  from (values
    ('Greeter', 'management', 'Welcomes new members with a message, gives them starter roles and logs who joins and leaves.', '#ff7a45', '/bots/greeter.svg', array['welcome', 'servermanagement', 'roles']),
    ('Gatekeeper', 'verification', 'Keeps raiders and alt accounts out: new members verify before they can talk.', '#22c55e', '/bots/gatekeeper.svg', array['verification', 'security', 'antiraid']),
    ('Word Guess', 'wordle', 'A shared word game for your channel — six guesses to find the five-letter word.', '#4caf50', '/bots/wordguess.svg', array['games', 'fun']),
    ('Announcer', 'site', 'Posts updates from your website, stream or service into a channel through a webhook.', '#ec4899', '/bots/announcer.svg', array['webhooks', 'announcements', 'notifications']),
    ('Mod Toolkit', 'venband', 'Moderation for your staff — purge messages, ban, kick, time out, lock channels and look people up.', '#ef4444', '/bots/modtoolkit.svg', array['moderation', 'servermanagement', 'security'])
  ) as v(name, preset, description, color, icon, tags)
 where exists (select 1 from public.profiles where id = '3fff0000-0000-4000-8000-0000000000bd')
   and not exists (select 1 from public.applications a
                    where a.owner_id = '3fff0000-0000-4000-8000-0000000000bd' and a.name = v.name);

notify pgrst, 'reload schema';

-- ---------------------------------------------------------------- 20261106110000_server_templates.sql
-- =============================================================================
-- Shareable server templates (20261106110000)
--
-- A template is a snapshot of a server's STRUCTURE — roles (names, colours,
-- permissions, icons), categories, channels (types, topics, privacy, settings)
-- and role-based permission overrides. Never messages, members or files.
-- Share the link (venband.com/template/CODE); anyone can preview it and build a
-- new server from it. "Sync" refreshes the snapshot from the server.
--
-- Safe to run more than once.
-- =============================================================================

create table if not exists public.server_templates (
  id          uuid primary key default gen_random_uuid(),
  code        text not null unique check (code ~ '^[A-Za-z0-9]{8,16}$'),
  server_id   uuid references public.servers (id) on delete set null,
  author_id   uuid not null references public.profiles (id) on delete cascade,
  name        text not null check (char_length(btrim(name)) between 2 and 60),
  description text not null default '' check (char_length(description) <= 300),
  public      boolean not null default false,
  snapshot    jsonb not null check (pg_column_size(snapshot) < 262144),
  uses        integer not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index if not exists server_templates_server_idx on public.server_templates (server_id);
create index if not exists server_templates_public_idx on public.server_templates (public, uses desc) where public;
alter table public.server_templates enable row level security;
drop policy if exists server_templates_select on public.server_templates;
create policy server_templates_select on public.server_templates for select to authenticated
  using (author_id = auth.uid() or public or (server_id is not null and public.has_permission(server_id, 2)));
drop policy if exists server_templates_delete on public.server_templates;
create policy server_templates_delete on public.server_templates for delete to authenticated
  using (author_id = auth.uid() or (server_id is not null and public.has_permission(server_id, 2)));
revoke insert, update on public.server_templates from authenticated, anon;
grant select, delete on public.server_templates to authenticated;

-- ------------------------------------------------------------- snapshot --
create or replace function public.server_snapshot(p_server uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'v', 1,
    'everyone', (select r.permissions from public.roles r where r.server_id = p_server and r.is_default limit 1),
    'roles', coalesce((select jsonb_agg(jsonb_build_object(
        'key', r.id, 'name', r.name, 'color', r.color, 'color2', r.color2, 'permissions', r.permissions,
        'position', r.position, 'hoist', r.hoist, 'icon', r.icon, 'description', r.description, 'mentionable', r.mentionable)
        order by r.position)
      from public.roles r where r.server_id = p_server and not r.is_default), '[]'::jsonb),
    'categories', to_jsonb(coalesce(s.categories, '{}'::text[])),
    'channels', coalesce((select jsonb_agg(jsonb_build_object(
        'key', c.id, 'name', c.name, 'type', c.type, 'topic', c.topic, 'category', c.category, 'position', c.position,
        'is_private', c.is_private, 'settings', c.settings, 'color', c.color,
        'access', coalesce((select jsonb_agg(a.role_id) from public.channel_role_access a where a.channel_id = c.id), '[]'::jsonb))
        order by c.position)
      from public.channels c where c.server_id = p_server), '[]'::jsonb),
    -- role overrides only (member overrides are about people, not structure)
    'overwrites', coalesce((select jsonb_agg(jsonb_build_object(
        'channel', o.channel_id, 'category', o.category,
        'role', case when r.is_default then 'everyone' else o.target_id::text end, 'allow', o.allow, 'deny', o.deny))
      from public.channel_overwrites o join public.roles r on r.id = o.target_id
      where o.server_id = p_server and o.target_type = 'role'), '[]'::jsonb),
    'welcome', s.welcome_channel_id,
    'rules', to_jsonb(coalesce(s.rules, '{}'::text[])),
    'description', s.description)
  from public.servers s where s.id = p_server;
$$;

create or replace function public.create_template(p_server uuid, p_name text, p_description text default '', p_public boolean default false)
returns text language plpgsql security definer set search_path = '' as $$
declare
  v_code text;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not public.has_permission(p_server, 2) then raise exception 'you need Manage Server to make a template'; end if;
  if (select count(*) from public.server_templates where author_id = auth.uid()) >= 20 then
    raise exception 'you can have up to 20 templates';
  end if;
  loop
    v_code := translate(encode(extensions.gen_random_bytes(9), 'base64'), '+/=', 'xyz');
    v_code := left(regexp_replace(v_code, '[^A-Za-z0-9]', '', 'g'), 10);
    exit when char_length(v_code) = 10 and not exists (select 1 from public.server_templates where code = v_code);
  end loop;
  insert into public.server_templates (code, server_id, author_id, name, description, public, snapshot)
  values (v_code, p_server, auth.uid(), btrim(p_name), btrim(coalesce(p_description, '')), coalesce(p_public, false), public.server_snapshot(p_server));
  return v_code;
end;
$$;

-- refresh the snapshot from the server it came from
create or replace function public.sync_template(p_template uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  t public.server_templates%rowtype;
begin
  select * into t from public.server_templates where id = p_template;
  if not found then raise exception 'not found'; end if;
  if t.server_id is null then raise exception 'the server this template came from is gone'; end if;
  if not public.has_permission(t.server_id, 2) then raise exception 'you need Manage Server'; end if;
  update public.server_templates set snapshot = public.server_snapshot(t.server_id), updated_at = now() where id = p_template;
end;
$$;

-- what a template link shows before you use it
create or replace function public.template_preview(p_code text)
returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'code', t.code, 'name', t.name, 'description', t.description, 'uses', t.uses, 'updated_at', t.updated_at,
    'author', (select p.username from public.profiles p where p.id = t.author_id),
    'roles', (select coalesce(jsonb_agg(jsonb_build_object('name', r ->> 'name', 'color', r ->> 'color')), '[]'::jsonb)
                from jsonb_array_elements(t.snapshot -> 'roles') r),
    'channels', (select coalesce(jsonb_agg(jsonb_build_object('name', c ->> 'name', 'type', c ->> 'type', 'category', c ->> 'category')
                                 order by (c ->> 'position')::int), '[]'::jsonb)
                   from jsonb_array_elements(t.snapshot -> 'channels') c))
  from public.server_templates t
  where t.code = p_code and auth.uid() is not null;
$$;

create or replace function public.template_gallery(p_query text default '')
returns table (code text, name text, description text, uses integer, author text, channels integer, roles integer)
language sql stable security definer set search_path = '' as $$
  select t.code, t.name, t.description, t.uses, p.username,
         jsonb_array_length(t.snapshot -> 'channels'), jsonb_array_length(t.snapshot -> 'roles')
  from public.server_templates t join public.profiles p on p.id = t.author_id
  where t.public and auth.uid() is not null
    and (coalesce(btrim(p_query), '') = '' or t.name ilike '%' || btrim(p_query) || '%' or t.description ilike '%' || btrim(p_query) || '%')
  order by t.uses desc, t.updated_at desc
  limit 60;
$$;

-- ------------------------------------------------- build a server from one --
create or replace function public.create_server_from_template(p_code text, p_name text, p_icon_color text default '#7c5cff')
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := auth.uid();
  t public.server_templates%rowtype;
  v_server uuid;
  v_everyone uuid;
  v_roles jsonb := '{}'::jsonb;    -- old role id -> new role id
  v_chans jsonb := '{}'::jsonb;    -- old channel id -> new channel id
  v_id uuid;
  r jsonb;
  c jsonb;
  o jsonb;
  a jsonb;
begin
  if v_uid is null then raise exception 'not authenticated'; end if;
  if not public.account_can('create') then raise exception 'your account can''t create servers right now'; end if;
  if (select count(*) from public.servers where owner_id = v_uid) >= 100 then raise exception 'server limit reached'; end if;
  select * into t from public.server_templates where code = p_code;
  if not found then raise exception 'that template doesn''t exist (any more)'; end if;
  if char_length(btrim(coalesce(p_name, ''))) < 2 then raise exception 'give your server a name'; end if;

  insert into public.servers (name, owner_id, icon_color, categories, rules, description)
  values (left(btrim(p_name), 100), v_uid, coalesce(p_icon_color, '#7c5cff'),
          coalesce(array(select jsonb_array_elements_text(t.snapshot -> 'categories')), '{}'),
          coalesce(array(select jsonb_array_elements_text(t.snapshot -> 'rules')), '{}'),
          left(coalesce(t.snapshot ->> 'description', ''), 500))
  returning id into v_server;
  insert into public.server_members (server_id, user_id) values (v_server, v_uid);
  insert into public.roles (server_id, name, color, permissions, position, is_default)
  values (v_server, '@everyone', '#99aab5', coalesce((t.snapshot ->> 'everyone')::bigint, 0), 0, true)
  returning id into v_everyone;

  for r in select * from jsonb_array_elements(t.snapshot -> 'roles') loop
    insert into public.roles (server_id, name, color, color2, permissions, position, hoist, icon, description, mentionable)
    values (v_server, left(r ->> 'name', 100), coalesce(r ->> 'color', '#99aab5'), r ->> 'color2',
            coalesce((r ->> 'permissions')::bigint, 0), coalesce((r ->> 'position')::int, 1),
            coalesce((r ->> 'hoist')::boolean, false), r ->> 'icon', coalesce(r ->> 'description', ''),
            coalesce((r ->> 'mentionable')::boolean, true))
    returning id into v_id;
    v_roles := v_roles || jsonb_build_object(r ->> 'key', v_id);
  end loop;
  v_roles := v_roles || jsonb_build_object('everyone', v_everyone);

  for c in select * from jsonb_array_elements(t.snapshot -> 'channels') loop
    insert into public.channels (server_id, type, name, topic, category, position, is_private, settings, color)
    values (v_server, c ->> 'type', c ->> 'name', coalesce(c ->> 'topic', ''), coalesce(c ->> 'category', ''),
            coalesce((c ->> 'position')::int, 0), coalesce((c ->> 'is_private')::boolean, false),
            coalesce(c -> 'settings', '{}'::jsonb), c ->> 'color')
    returning id into v_id;
    v_chans := v_chans || jsonb_build_object(c ->> 'key', v_id);
    for a in select * from jsonb_array_elements(coalesce(c -> 'access', '[]'::jsonb)) loop
      if v_roles ? (a #>> '{}') then
        insert into public.channel_role_access (channel_id, role_id) values (v_id, (v_roles ->> (a #>> '{}'))::uuid) on conflict do nothing;
      end if;
    end loop;
  end loop;

  for o in select * from jsonb_array_elements(coalesce(t.snapshot -> 'overwrites', '[]'::jsonb)) loop
    if not (v_roles ? (o ->> 'role')) then continue; end if;
    if o ->> 'channel' is not null and not (v_chans ? (o ->> 'channel')) then continue; end if;
    insert into public.channel_overwrites (server_id, channel_id, category, target_type, target_id, allow, deny)
    values (v_server, (v_chans ->> (o ->> 'channel'))::uuid, case when o ->> 'channel' is null then o ->> 'category' end,
            'role', (v_roles ->> (o ->> 'role'))::uuid, coalesce((o ->> 'allow')::bigint, 0), coalesce((o ->> 'deny')::bigint, 0));
  end loop;

  if t.snapshot ->> 'welcome' is not null and v_chans ? (t.snapshot ->> 'welcome') then
    perform set_config('venband.mod', 'on', true);
    update public.servers set welcome_channel_id = (v_chans ->> (t.snapshot ->> 'welcome'))::uuid where id = v_server;
    perform set_config('venband.mod', 'off', true);
  end if;
  update public.server_templates set uses = uses + 1 where id = t.id;
  return v_server;
end;
$$;

revoke execute on function public.server_snapshot(uuid) from public, anon, authenticated;
revoke execute on function public.create_template(uuid, text, text, boolean) from public, anon;
grant execute on function public.create_template(uuid, text, text, boolean) to authenticated;
revoke execute on function public.sync_template(uuid) from public, anon;
grant execute on function public.sync_template(uuid) to authenticated;
revoke execute on function public.template_preview(text) from public, anon;
grant execute on function public.template_preview(text) to authenticated;
revoke execute on function public.template_gallery(text) from public, anon;
grant execute on function public.template_gallery(text) to authenticated;
revoke execute on function public.create_server_from_template(text, text, text) from public, anon;
grant execute on function public.create_server_from_template(text, text, text) to authenticated;

